[CmdletBinding()]
param(
 [Parameter(Mandatory=$true)][string]$InputPath,
 [Parameter(Mandatory=$true)][string]$OutputDirectory,
 [ValidateRange(0,100)][double]$DriftPercent=5,
 [ValidateRange(0,100)][double]$DriftAbsoluteMs=.5
)
$ErrorActionPreference='Stop'
function F($object,[string]$key,$fallback=$null){if($null -eq $object){return $fallback};if($object -is [Collections.IDictionary]){if($object.Contains($key)){return $object[$key]}}else{$property=$object.PSObject.Properties[$key];if($null -ne $property){return $property.Value}};return $fallback}
function N($value){if($null -eq $value -or $value -is [bool] -or $value -is [string]){return $null};try{$number=[double]$value;if([double]::IsNaN($number)-or[double]::IsInfinity($number)){return $null};return $number}catch{return $null}}
function Metric($raw,[bool]$gpu=$false){
 $count=N (F $raw 'samples');$available=(F $raw 'available') -eq $true -and $null -ne $count -and $count -gt 0
 $values=@{};foreach($key in @('p50','p95','p99')){$v=N (F $raw $key);if($null -ne $v -and ($v -lt 0 -or ($gpu -and ($v -le 0 -or $v -gt 1000)))){$v=$null};$values[$key]=$(if($available){$v}else{$null})}
 $available=$available -and $null -ne $values.p50 -and $null -ne $values.p95
 if(-not $available){$values.p50=$null;$values.p95=$null;$values.p99=$null}
 [ordered]@{available=$available;p50=$values.p50;p95=$values.p95;p99=$values.p99;samples=$count;missing=(N (F $raw 'missing'));rejected=(N (F $raw 'rejected'));rejectedRaw=@(F $raw 'rejectedRaw' @());status=$(if($available){'Measured'}elseif($null -eq $raw){'Unknown: no series'}elseif((F $raw 'status')-eq'Measured'){'Unknown: invalid or unavailable aggregate despite raw Measured status'}else{F $raw 'status' 'Unknown: unavailable or invalid aggregate'});sourceStatus=(F $raw 'sourceStatus');note=(F $raw 'note')}
}
function Delta($value,$first,$last,[double]$weight){$result=[ordered]@{weight=$weight;p50=$null;p95=$null;p99=$null;interpolatedA=[ordered]@{p50=$null;p95=$null;p99=$null};status='Unknown: valid current and both A series required'};foreach($key in @('p50','p95','p99')){if($null -ne $value[$key]-and$null -ne $first[$key]-and$null -ne $last[$key]){$base=$first[$key]+($last[$key]-$first[$key])*$weight;$result.interpolatedA[$key]=$base;$result[$key]=$value[$key]-$base}};if($null -ne $result.p50-and$null -ne $result.p95){$result.status='Descriptive quantile difference; ordinal A interpolation'};return $result}
function Drift($first,$last){$difference=$null;$percent=$null;$flag=$null;$tolerance=$null;$delta95=$null;$flag95=$null;$tolerance95=$null;if($null -ne $first.p50-and$null -ne $last.p50){$difference=$last.p50-$first.p50;$tolerance=[Math]::Max($DriftAbsoluteMs,[Math]::Abs($first.p50)*$DriftPercent/100);$flag=[Math]::Abs($difference)-gt$tolerance;if($first.p50-ne0){$percent=100*$difference/[Math]::Abs($first.p50)}};if($null-ne$first.p95-and$null-ne$last.p95){$delta95=$last.p95-$first.p95;$tolerance95=[Math]::Max($DriftAbsoluteMs,[Math]::Abs($first.p95)*$DriftPercent/100);$flag95=[Math]::Abs($delta95)-gt$tolerance95};$any=$(if($flag-eq$true-or$flag95-eq$true){$true}elseif($null-ne$flag-and$null-ne$flag95){$false}else{$null});[ordered]@{firstP50=$first.p50;lastP50=$last.p50;deltaMs=$difference;deltaPercent=$percent;toleranceMs=$tolerance;firstP95=$first.p95;lastP95=$last.p95;deltaP95Ms=$delta95;toleranceP95Ms=$tolerance95;flagged=$any;status=$(if($null-eq$any){'Unknown'}elseif($any){'Drift flagged'}else{'Within configured reporting tolerance'})}}
function Resources($raw){$result=[ordered]@{available=(F $raw 'available')-eq$true};foreach($k in @('roomTextures','lookTextures','styleTextures','styleMaterials','roomBytes','lookBytes','styleBytes')){$result[$k]=$(if($result.available){N (F $raw $k)}else{$null})};$result.totalTextures=$(if($null-ne$result.roomTextures-and$null-ne$result.lookTextures){$result.roomTextures+$result.lookTextures}else{$null});$result.totalPixelPayloadBytes=$(if($null-ne$result.roomBytes-and$null-ne$result.lookBytes){$result.roomBytes+$result.lookBytes}else{$null});$result.error=F $raw 'error';$result.coreError=F $raw 'coreError';$result.coverageError=F $raw 'styleCoverageError';return $result}
function Budget($limit,$metric,$phases,[bool]$reliable){$values=@();foreach($p in $phases){if($p.state-in@('MaterialLighting','BlueComplete')){foreach($q in @('p50','p95')){if($null-ne$p[$metric][$q]){$values+=$p[$metric][$q]}}}};$max=$(if($values.Count){($values|Measure-Object -Maximum).Maximum}else{$null});[ordered]@{status=$(if(-not$reliable-or$values.Count-ne4){'Unknown'}elseif($max-gt$limit){'NotMet'}else{'Met'});targetMs=$limit;worstObservedIncrementMs=$max;basis='Both B/C p50 and p95 whole-frame quantile differences versus ordinal interpolated A; not exclusive stage timings'} }
function Format($v){if($null-eq$v){return 'Unknown'};return ([double]$v).ToString('0.000',[Globalization.CultureInfo]::InvariantCulture)}
function Pair($metric){return ('{0} / {1}'-f(Format $metric.p50),(Format $metric.p95))}

$source=(Resolve-Path -LiteralPath $InputPath).Path
$destination=[IO.Path]::GetFullPath($OutputDirectory)
if([string]::Equals($source,(Join-Path $destination 'summary.json'),[StringComparison]::OrdinalIgnoreCase)){throw 'Output must not overwrite raw input.'}
$raw=Get-Content -LiteralPath $source -Raw|ConvertFrom-Json
$rawPhases=@(F $raw 'phases' @());$phases=@();$warnings=[Collections.Generic.List[string]]::new()
foreach($p in $rawPhases){
 $scopes=@();foreach($s in @(F $p 'styleSamplers' @())){$scopes+=[ordered]@{name=(F $s 'name');expectedExecuted=(F $s 'expectedExecuted');status=(F $s 'status');cpuBlocks=(F $s 'cpuBlocks');gpuBlocks=(F $s 'gpuBlocks');inlineBlocks=(F $s 'inlineBlocks');unexpectedSampleFrames=(F $s 'unexpectedSampleFrames');cpu=(Metric (F $s 'cpu'));gpu=(Metric (F $s 'gpu') $true);inlineCpu=(Metric (F $s 'inlineCpu'))}}
 $waits=@();foreach($w in @(F $p 'namedThreadAndWaitScopes' @())){$row=Metric $w;$row.name=F $w 'name';$waits+=$row}
 $counts=@();foreach($c in @(F $p 'renderCounters' @())){$row=Metric $c;$row.name=F $c 'name';$counts+=$row}
 $phases+=[ordered]@{name=(F $p 'name');state=(F $p 'state');toon=(F $p 'toon');cameraFrames=(N (F $p 'cameraFrames'));uniqueFrameTiming=(N (F $p 'uniqueFrameTiming'));missingFrameTiming=(N (F $p 'missingFrameTiming'));duplicateFrameTiming=(N (F $p 'duplicateFrameTiming'));focusedFrames=(N (F $p 'focusedFrames'));backgroundFrames=(N (F $p 'backgroundFrames'));frameTimingError=(F $p 'frameTimingError');environmentClockRunning=(F $p 'environmentClockRunning');environmentStartHour=(F $p 'environmentStartHour');environmentEndHour=(F $p 'environmentEndHour');frame=(Metric (F $p 'wall'));gpu=(Metric (F $p 'gpuFrame') $true);cpuFrameInclusive=(Metric (F $p 'cpuFrame'));cpuMainInclusive=(Metric (F $p 'cpuMainInclusive'));cpuRenderInclusive=(Metric (F $p 'cpuRenderInclusive'));presentWait=(Metric (F $p 'mainPresentWait'));mainResidual=(Metric (F $p 'mainMinusPresentResidual'));cpuEffectiveWork=(Metric (F $p 'cpuEffectiveWork'));waits=$waits;renderCounters=$counts;samplers=$scopes;resources=(Resources (F $p 'end'));frameDeltaFromInterpolatedA=$null;gpuDeltaFromInterpolatedA=$null;cpuEffectiveDeltaFromInterpolatedA=$null}
}
$orderedStates=@('Previous','MaterialLighting','BlueComplete','Previous');$sequenceValid=$phases.Count-eq4
if($sequenceValid){for($i=0;$i-lt4;$i++){if($phases[$i].state-ne$orderedStates[$i]){$sequenceValid=$false}}}
$drift=[ordered]@{frame=$null;gpu=$null;cpuMainInclusive=$null;cpuRenderInclusive=$null;reportingTolerance=[ordered]@{percent=$DriftPercent;absoluteMs=$DriftAbsoluteMs}}
$resourceReturn=[ordered]@{reportedReturned=(F $raw 'originalTrackedBuffersReturned');detailedMatch=$null;changedFields=@();scope='Tracked RT payload/category counts only; not total process VRAM'}
if($sequenceValid){
 foreach($metric in @('frame','gpu','cpuMainInclusive','cpuRenderInclusive')){$drift[$metric]=Drift $phases[0][$metric] $phases[3][$metric]}
 for($i=0;$i-lt4;$i++){$weight=$i/3.0;$phases[$i].frameDeltaFromInterpolatedA=Delta $phases[$i].frame $phases[0].frame $phases[3].frame $weight;$phases[$i].gpuDeltaFromInterpolatedA=Delta $phases[$i].gpu $phases[0].gpu $phases[3].gpu $weight;$phases[$i].cpuEffectiveDeltaFromInterpolatedA=Delta $phases[$i].cpuEffectiveWork $phases[0].cpuEffectiveWork $phases[3].cpuEffectiveWork $weight}
 $first=$phases[0].resources;$last=$phases[3].resources;$changes=@();$known=$first.available-and$last.available
 foreach($k in @('roomTextures','lookTextures','styleTextures','styleMaterials','roomBytes','lookBytes','styleBytes')){if($null-eq$first[$k]-or$null-eq$last[$k]){$known=$false}elseif($first[$k]-ne$last[$k]){$changes+=[ordered]@{field=$k;before=$first[$k];after=$last[$k]}}};$resourceReturn.detailedMatch=$(if($known){$changes.Count-eq0}else{$null});$resourceReturn.changedFields=$changes
}
$measurementValid=(F $raw 'completed')-eq$true-and(F $raw 'controlsRestored')-eq$true-and$sequenceValid-and@(F $raw 'errors' @()).Count-eq0-and(F $raw 'width')-eq1600-and(F $raw 'height')-eq900-and(F $raw 'warmFrames')-ge60-and(F $raw 'sampleFrames')-ge300-and(F (F $raw 'quality') 'certified')-eq$true-and(F $raw 'editor')-eq$false-and(F $raw 'developmentBuild')-eq$false
foreach($p in $phases){if($null-eq$p.cameraFrames-or$p.cameraFrames-lt300){$measurementValid=$false};if($p.environmentClockRunning){$warnings.Add($p.name+': natural clock advanced; lighting was not fixed')};if($p.backgroundFrames-gt0){$warnings.Add($p.name+': background frames recorded; foreground state must be considered')};foreach($s in $p.samplers){if($s.expectedExecuted-and(-not$s.cpu.available-or-not$s.gpu.available)){$warnings.Add($p.name+'/'+$s.name+': one or more expected Release scope timings unavailable')}}}
if(-not$measurementValid){$warnings.Add('Incomplete/invalid formal Release conditions; numeric observations remain descriptive')}
$anomalyFree=(F $raw 'gpuAnomalyFree')-eq$true
foreach($p in $phases){if($p.gpu.rejected-gt0){$anomalyFree=$false};foreach($s in $p.samplers){if($s.gpu.rejected-gt0){$anomalyFree=$false}}}
if(-not$anomalyFree){$warnings.Add('GPU anomaly-free status not certified; inspect raw rejected values')}
$gpuSufficient=$true;foreach($p in $phases){if($null-eq$p.gpu.samples-or$p.gpu.samples-lt30){$gpuSufficient=$false;$warnings.Add($p.name+': fewer than 30 valid unique GPU frame samples; increment budget remains Unknown')}}
$driftFlag=$false;foreach($key in @('frame','gpu','cpuMainInclusive','cpuRenderInclusive')){if($null-ne$drift[$key]-and$drift[$key].flagged-eq$true){$driftFlag=$true;$warnings.Add('Repeated A drift flagged: '+$key)}}
$gpuReliable=$measurementValid-and$anomalyFree-and$gpuSufficient-and-not$driftFlag-and$null-ne$drift.gpu-and$drift.gpu.flagged-eq$false
$effectiveAvailable=$sequenceValid-and@($phases|Where-Object{-not$_.cpuEffectiveWork.available}).Count-eq0
$gpuBudget=Budget .5 'gpuDeltaFromInterpolatedA' $phases $gpuReliable
$cpuBudget=Budget .3 'cpuEffectiveDeltaFromInterpolatedA' $phases ($measurementValid-and$effectiveAvailable-and-not$driftFlag)
$overall=$(if($gpuBudget.status-eq'NotMet'-or$cpuBudget.status-eq'NotMet'){'NotMet'}elseif($gpuBudget.status-eq'Met'-and$cpuBudget.status-eq'Met'){'Met'}else{'Unknown'})
$p95Values=@($phases|ForEach-Object{$_.frame.p95}|Where-Object{$null-ne$_});$frameOver=@($p95Values|Where-Object{$_-gt(1000/60.0)}).Count-gt0
$summary=[ordered]@{schema='SurfaceLightingCostSummary/v1';source=$source;sourceSha256=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash;synthetic=(F $raw 'synthetic' $false);generatedUtc=[DateTime]::UtcNow.ToString('O');measurementValid=$measurementValid;completed=(F $raw 'completed');stopReason=(F $raw 'stopReason');controlsRestored=(F $raw 'controlsRestored');device=(F $raw 'device');graphics=(F $raw 'graphics');resolution=@((F $raw 'width'),(F $raw 'height'));quality=(F $raw 'quality');grass=(F $raw 'grass');errors=@(F $raw 'errors' @());baselineInterpolation='Phase ordinal sample centers: B=1/3, C=2/3 between A endpoints. Raw probe has no per-phase timestamps; not a wall-time interpolation or exclusive incremental cost. Quantile differences are descriptive.';baselineDrift=$drift;phases=$phases;resourceReturn=$resourceReturn;budgets=[ordered]@{gpuIncrement=$gpuBudget;cpuEffectiveIncrement=$cpuBudget;combined=[ordered]@{status=$overall};stable60=[ordered]@{status=$(if($frameOver){'NotMet'}else{'Unknown'});targetFrameMs=(1000/60.0);note='If any observed p95 exceeds 16.667ms, this window fails. Otherwise a short A/B/C/A run does not certify independent sustained 60FPS.'}};warnings=@($warnings);interpretation='CPU main/render/frame are inclusive. Present wait is separate; main-minus-present still includes other waits/native work. Named scopes may overlap and are never summed/subtracted. Missing values stay null/Unknown; measured zero waits/counters remain zero. Render counters are latest completed frames. No GPU/CPU attribution beyond available measurements.'}
[IO.Directory]::CreateDirectory($destination)|Out-Null
$summary|ConvertTo-Json -Depth 40|Set-Content -LiteralPath (Join-Path $destination 'summary.json') -Encoding utf8
$md=[Collections.Generic.List[string]]::new();$md.Add('# SurfaceLighting cost summary');$md.Add('');$md.Add('Raw source: `'+$source+'`');$md.Add('');$md.Add(('Formal conditions: **{0}**; GPU increment: **{1}**; CPU effective increment: **{2}**; combined: **{3}**.'-f$measurementValid,$gpuBudget.status,$cpuBudget.status,$overall));$md.Add('');$md.Add('| State | Frame p50/p95 ms | GPU p50/p95 ms | GPU delta vs A ms | CPU main/render inclusive p50 ms | Present/residual p50 ms |');$md.Add('|---|---:|---:|---:|---:|---:|')
foreach($p in $phases){$delta=$(if($null-ne$p.gpuDeltaFromInterpolatedA){Pair $p.gpuDeltaFromInterpolatedA}else{'Unknown'});$md.Add(('| {0} | {1} | {2} | {3} | {4} / {5} | {6} / {7} |'-f$p.name,(Pair $p.frame),(Pair $p.gpu),$delta,(Format $p.cpuMainInclusive.p50),(Format $p.cpuRenderInclusive.p50),(Format $p.presentWait.p50),(Format $p.mainResidual.p50)))}
$md.Add('');$md.Add('A interpolation uses phase order (B 1/3, C 2/3), not unavailable stage timestamps. CPU effective work remains Unknown unless measured as a complete non-overlapping decomposition. Inclusive CPU, residual and waits must not be summed or treated as effective work.');$md.Add('');$md.Add('| State / series | p50/p95 | Availability / note |');$md.Add('|---|---:|---|')
foreach($p in $phases){foreach($c in $p.renderCounters){$md.Add(('| {0} / {1} | {2} | {3} |'-f$p.name,$c.name,(Pair $c),$c.status))};foreach($w in $p.waits){$md.Add(('| {0} / {1} | {2} ms | {3}; possibly overlapping |'-f$p.name,$w.name,(Pair $w),$w.status))};foreach($s in $p.samplers){$md.Add(('| {0} / {1} | CPU {2}; GPU {3}; inline {4} ms | expected={5}; Release timings may be unavailable |'-f$p.name,$s.name,(Pair $s.cpu),(Pair $s.gpu),(Pair $s.inlineCpu),$s.expectedExecuted))}}
$md.Add('');$md.Add(('Tracked RT return: reported={0}; detailed category match={1}. Payload is an estimate, not total VRAM.'-f$resourceReturn.reportedReturned,$(if($null-eq$resourceReturn.detailedMatch){'Unknown'}else{$resourceReturn.detailedMatch})));$md.Add('');$md.Add('| State | Room RT / Look RT | Tracked payload bytes |');$md.Add('|---|---:|---:|');foreach($p in $phases){$md.Add(('| {0} | {1} / {2} | {3} |'-f$p.name,$(if($null-eq$p.resources.roomTextures){'Unknown'}else{$p.resources.roomTextures}),$(if($null-eq$p.resources.lookTextures){'Unknown'}else{$p.resources.lookTextures}),$(if($null-eq$p.resources.totalPixelPayloadBytes){'Unknown'}else{$p.resources.totalPixelPayloadBytes})))};$md.Add('');$md.Add('Stable60: **'+$summary.budgets.stable60.status+'**. '+$summary.budgets.stable60.note);$md.Add('');foreach($w in $warnings){$md.Add('- '+$w)}
[IO.File]::WriteAllLines((Join-Path $destination 'summary.md'),$md,[Text.UTF8Encoding]::new($false))
[pscustomobject]@{summary=(Join-Path $destination 'summary.json');markdown=(Join-Path $destination 'summary.md');measurementValid=$measurementValid;gpuBudget=$gpuBudget.status;cpuEffectiveBudget=$cpuBudget.status;combined=$overall;synthetic=$summary.synthetic}
